#include <array>
#include <cstddef>

struct WindowSize {
    int width;
    int height;
};

enum class ChoiceState {
    selected,
    invalid_setting,
    unknown_area,
    no_candidate
};

struct WindowChoice {
    ChoiceState state;
    std::size_t index = 0;
};

template <std::size_t N>
WindowChoice choose_window_preset(const std::array<WindowSize, N>& presets,
                                  int requested,
                                  WindowSize area)
{
    // requested가 음수이거나 목록 범위 밖이면 무효 설정.
    if (requested < 0 || static_cast<std::size_t>(requested) >= N) {
        return WindowChoice{ChoiceState::invalid_setting, 0};
    }

    // 창 영역의 한 변이라도 0 이하이면 알 수 없는 영역.
    if (area.width <= 0 || area.height <= 0) {
        return WindowChoice{ChoiceState::unknown_area, 0};
    }

    // requested 인덱스에서 0까지 역순 검사. unsigned 언더플로 방지.
    std::size_t remaining = static_cast<std::size_t>(requested) + 1;
    while (remaining > 0) {
        const std::size_t i = --remaining;
        const WindowSize& s = presets[i];
        if (s.width > 0 && s.height > 0 &&
            s.width <= area.width && s.height <= area.height) {
            return WindowChoice{ChoiceState::selected, i};
        }
    }

    return WindowChoice{ChoiceState::no_candidate, 0};
}
